namespace simp {

Parser::Parser(std::vector<Token> tokens, std::ostream* traceOutput)
    : tokens_(std::move(tokens)), traceOutput_(traceOutput) {}

const Token& Parser::current() const {
    return tokens_[current_];
}

const Token& Parser::previous() const {
    return tokens_[current_ - 1];
}

bool Parser::check(TokenType type) const {
    return current().type == type;
}

bool Parser::match(TokenType type) {
    if (!check(type)) {
        return false;
    }
    ++current_;
    return true;
}

bool Parser::startsOutOfLineDefinition() const {
    std::size_t afterType = current_;
    switch (current().type) {
    case TokenType::Identifier:
        ++afterType;
        while (afterType + 1 < tokens_.size() &&
               tokens_[afterType].type == TokenType::Dot &&
               tokens_[afterType + 1].type == TokenType::Identifier) {
            afterType += 2;
        }
        break;
    case TokenType::Int:
    case TokenType::Bool:
    case TokenType::FloatType:
    case TokenType::Unsigned:
    case TokenType::StrgType:
    case TokenType::ListType:
    case TokenType::DictType:
    case TokenType::BufferType:
    case TokenType::HandleType:
    case TokenType::AnyType:
    case TokenType::TypeType:
    case TokenType::Void:
        ++afterType;
        break;
    default:
        return false;
    }
    return afterType + 2 < tokens_.size() &&
           tokens_[afterType].type == TokenType::Identifier &&
           tokens_[afterType + 1].type == TokenType::Dot &&
           tokens_[afterType + 2].type == TokenType::Identifier;
}

void Parser::skipNewlines() {
    while (match(TokenType::Newline)) {}
}

void Parser::consumeStatementTerminator() {
    if (match(TokenType::Newline)) {
        skipNewlines();
        return;
    }
    if (!check(TokenType::RightBrace) && !check(TokenType::End)) {
        error(current(), "expected newline after statement");
    }
}

const Token& Parser::consume(TokenType type, const char* expectation) {
    if (check(type)) {
        return tokens_[current_++];
    }
    error(current(), std::string("expected ") + expectation + ", found " +
                         tokenTypeName(current().type));
}

[[noreturn]] void Parser::error(const Token& token, const std::string& message) const {
    throw DiagnosticError(token.location, message);
}

void Parser::validateFormatString(Expression& format) const {
    const auto isIdentifierStart = [](char character) {
        return (character >= 'a' && character <= 'z') ||
               (character >= 'A' && character <= 'Z') || character == '_';
    };
    const auto isIdentifierPart = [&isIdentifierStart](char character) {
        return isIdentifierStart(character) || (character >= '0' && character <= '9');
    };

    std::vector<std::string> placeholderNames;
    std::string segment;
    bool hasPositionalPlaceholder = false;
    bool hasNamedPlaceholder = false;
    for (std::size_t index = 0; index < format.value.size();) {
        const char character = format.value[index];
        if (character == '{') {
            if (index + 1 < format.value.size() && format.value[index + 1] == '{') {
                segment += '{';
                index += 2;
                continue;
            }
            format.formatSegments.push_back(segment);
            segment.clear();
            if (index + 1 < format.value.size() && format.value[index + 1] == '}') {
                placeholderNames.emplace_back();
                hasPositionalPlaceholder = true;
                index += 2;
                continue;
            }

            std::size_t end = index + 1;
            while (end < format.value.size() && format.value[end] != '}') {
                ++end;
            }
            if (end == format.value.size()) {
                throw DiagnosticError(format.location, "unmatched '{' in formatted string");
            }
            if (end == index + 1 ||
                !isIdentifierStart(format.value[index + 1]) ||
                !std::all_of(format.value.begin() + static_cast<std::ptrdiff_t>(index + 2),
                             format.value.begin() + static_cast<std::ptrdiff_t>(end),
                             isIdentifierPart)) {
                throw DiagnosticError(format.location,
                                      "malformed placeholder name in formatted string");
            }
            placeholderNames.push_back(format.value.substr(index + 1, end - index - 1));
            hasNamedPlaceholder = true;
            index = end + 1;
            continue;
        }
        if (character == '}') {
            if (index + 1 < format.value.size() && format.value[index + 1] == '}') {
                segment += '}';
                index += 2;
                continue;
            }
            throw DiagnosticError(format.location, "unmatched '}' in formatted string");
        }
        segment += character;
        ++index;
    }
    format.formatSegments.push_back(segment);

    if (hasPositionalPlaceholder && hasNamedPlaceholder) {
        throw DiagnosticError(format.location,
                              "named and positional placeholders cannot be mixed");
    }
    if (format.argumentNames.size() != format.arguments.size() ||
        format.argumentNameLocations.size() != format.arguments.size()) {
        throw DiagnosticError(format.location, "invalid format argument metadata");
    }

    const bool hasNamedArgument = std::any_of(
        format.argumentNames.begin(), format.argumentNames.end(),
        [](const std::string& name) { return !name.empty(); });
    const bool hasPositionalArgument = std::any_of(
        format.argumentNames.begin(), format.argumentNames.end(),
        [](const std::string& name) { return name.empty(); });
    if (hasNamedArgument && hasPositionalArgument) {
        throw DiagnosticError(format.location,
                              "named and positional format arguments cannot be mixed");
    }

    if (hasNamedPlaceholder) {
        if (hasPositionalArgument) {
            throw DiagnosticError(format.location,
                                  "named and positional format arguments cannot be mixed");
        }
        for (std::size_t argumentIndex = 0;
             argumentIndex < format.argumentNames.size(); ++argumentIndex) {
            const auto& name = format.argumentNames[argumentIndex];
            if (std::find(placeholderNames.begin(), placeholderNames.end(), name) ==
                placeholderNames.end()) {
                throw DiagnosticError(format.argumentNameLocations[argumentIndex],
                                      "unused named format argument '" + name + "'");
            }
        }
        for (const auto& name : placeholderNames) {
            const auto argument = std::find(format.argumentNames.begin(),
                                            format.argumentNames.end(), name);
            if (argument == format.argumentNames.end()) {
                throw DiagnosticError(format.location,
                                      "missing named format argument '" + name + "'");
            }
            format.formatArgumentIndices.push_back(static_cast<std::size_t>(
                std::distance(format.argumentNames.begin(), argument)));
        }
        return;
    }

    if (hasNamedArgument) {
        const auto named = std::find_if(
            format.argumentNames.begin(), format.argumentNames.end(),
            [](const std::string& name) { return !name.empty(); });
        const auto argumentIndex = static_cast<std::size_t>(
            std::distance(format.argumentNames.begin(), named));
        if (placeholderNames.empty()) {
            throw DiagnosticError(format.argumentNameLocations[argumentIndex],
                                  "unused named format argument '" +
                                      format.argumentNames[argumentIndex] + "'");
        }
        throw DiagnosticError(format.argumentNameLocations[argumentIndex],
                              "named and positional format arguments cannot be mixed");
    }
    if (placeholderNames.size() != format.arguments.size()) {
        throw DiagnosticError(format.location,
                              "formatted string must have one '{}' placeholder per argument");
    }
    for (std::size_t index = 0; index < placeholderNames.size(); ++index) {
        format.formatArgumentIndices.push_back(index);
    }
}

void Parser::trace(const char* action) const {
    if (traceOutput_ != nullptr) {
        *traceOutput_ << "[parser] " << action << " at " << current().location.line << ":"
                      << current().location.column << " (" << tokenTypeName(current().type)
                      << ")\n";
    }
}

Program Parser::parseProgram(bool requireStart) {
    Program program;
    skipNewlines();
    while (check(TokenType::Import) || check(TokenType::Include) || check(TokenType::Class) ||
           check(TokenType::Namespace) || startsOutOfLineDefinition()) {
        if (check(TokenType::Import)) {
            program.imports.push_back(parseImport());
        } else if (check(TokenType::Include)) {
            error(current(), "'include' must be expanded before parsing");
        } else if (check(TokenType::Class)) {
            program.classes.push_back(parseClass());
        } else if (check(TokenType::Namespace)) {
            parseNamespace(program);
        } else {
            program.outOfLineMethods.push_back(parseOutOfLineMethodDefinition());
        }
        skipNewlines();
    }
    if (check(TokenType::Inline)) {
        error(current(), "'inline' is only allowed inside a function or method body");
    }
    if (!check(TokenType::Start)) {
        if (!requireStart && check(TokenType::End)) return program;
        error(current(), "program must contain exactly one top-level 'start' block");
    }
    const auto start = current();
    program.location = start.location;
    program.hasStart = true;
    trace("enter start block");
    ++current_;
    program.statements = parseBlock();
    skipNewlines();
    if (check(TokenType::Start)) {
        error(current(), "program contains more than one top-level 'start' block");
    }
    if (!check(TokenType::End)) {
        if (check(TokenType::Inline)) {
            error(current(), "'inline' is only allowed inside a function or method body");
        }
        error(current(), "only one top-level 'start' block is allowed");
    }
    return program;
}

Program Parser::parseModule() {
    Program program;
    skipNewlines();
    while (!check(TokenType::End)) {
        if (check(TokenType::Import)) {
            program.imports.push_back(parseImport());
        } else if (check(TokenType::Class)) {
            program.classes.push_back(parseClass());
        } else if (check(TokenType::Namespace)) {
            parseNamespace(program);
        } else if (startsOutOfLineDefinition()) {
            program.outOfLineMethods.push_back(parseOutOfLineMethodDefinition());
        } else if (check(TokenType::Start)) {
            error(current(), "imported module source cannot declare 'start'");
        } else if (check(TokenType::Inline)) {
            error(current(), "'inline' is only allowed inside a function or method body");
        } else {
            error(current(), "module source may contain only imports and declarations");
        }
        skipNewlines();
    }
    return program;
}

ImportDeclaration Parser::parseImport() {
    const auto keyword = consume(TokenType::Import, "'import'");
    const auto module = consume(TokenType::Identifier, "module name");
    consume(TokenType::As, "'as' after module name");
    const auto alias = consume(TokenType::Identifier, "import alias");
    consumeStatementTerminator();
    return {module.text, alias.text, {}, {}, false, keyword.location};
}

std::string Parser::parseQualifiedIdentifier(const char* expectation) {
    std::string name = consume(TokenType::Identifier, expectation).text;
    while (match(TokenType::Dot)) {
        name += "." + consume(TokenType::Identifier, expectation).text;
    }
    return name;
}

void Parser::parseNamespace(Program& program) {
    const auto keyword = consume(TokenType::Namespace, "'namespace'");
    const auto name = consume(TokenType::Identifier, "namespace name").text;
    skipNewlines();
    consume(TokenType::LeftBrace, "'{' after namespace name");

    const auto oldDepth = namespacePath_.size();
    namespacePath_.push_back(name);
    program.namespaces.push_back({namespacePath_, {}, keyword.location});
    while (!check(TokenType::RightBrace) && !check(TokenType::End)) {
        skipNewlines();
        if (check(TokenType::RightBrace) || check(TokenType::End)) break;
        if (check(TokenType::Namespace)) {
            parseNamespace(program);
        } else if (check(TokenType::Class)) {
            program.classes.push_back(parseClass());
        } else if (check(TokenType::Start)) {
            error(current(), "'start' cannot be declared inside a namespace");
        } else if (check(TokenType::Inline)) {
            error(current(), "'inline' is only allowed inside a function or method body");
        } else if (check(TokenType::Include)) {
            error(current(), "'include' is only allowed at top level");
        } else if (check(TokenType::Import)) {
            error(current(), "'import' is only allowed at top level");
        } else if (startsOutOfLineDefinition()) {
            program.outOfLineMethods.push_back(parseOutOfLineMethodDefinition());
        } else {
            error(current(), "namespace body may contain only namespace and class declarations");
        }
        skipNewlines();
    }
    consume(TokenType::RightBrace, "'}' after namespace body");
    namespacePath_.resize(oldDepth);
}

std::vector<Statement> Parser::parseBlock() {
    skipNewlines();
    consume(TokenType::LeftBrace, "'{'");
    std::vector<Statement> statements;
    while (!check(TokenType::RightBrace) && !check(TokenType::End)) {
        skipNewlines();
        if (check(TokenType::RightBrace) || check(TokenType::End)) {
            break;
        }
        statements.push_back(parseStatement());
        while (!pendingStatements_.empty()) {
            statements.push_back(std::move(pendingStatements_.front()));
            pendingStatements_.erase(pendingStatements_.begin());
        }
    }
    consume(TokenType::RightBrace, "'}'");
    return statements;
}

Statement Parser::parseStatement() {
    trace("parse statement");
    if (check(TokenType::Import)) {
        error(current(), "'import' is only allowed at top level");
    }
    if (check(TokenType::Include)) {
        error(current(), "'include' is only allowed at top level");
    }
    if (check(TokenType::Inline)) {
        return parseInlineC();
    }
    if (check(TokenType::Int) || check(TokenType::Bool) ||
        check(TokenType::FloatType) || check(TokenType::Unsigned) ||
        check(TokenType::StrgType) || check(TokenType::ListType) ||
        check(TokenType::DictType) || check(TokenType::BufferType) ||
        check(TokenType::HandleType) || check(TokenType::AnyType) ||
        check(TokenType::TypeType) || check(TokenType::Void)) {
        return parseDeclaration();
    }
    if (check(TokenType::Identifier)) {
        return parseIdentifierStatement();
    }
    if (check(TokenType::Print)) {
        return parsePrint();
    }
    if (check(TokenType::If)) {
        return parseIf();
    }
    if (check(TokenType::While)) {
        return parseWhile();
    }
    if (check(TokenType::Do)) {
        return parseDoWhile();
    }
    if (check(TokenType::For)) {
        return parseForEach();
    }
    if (check(TokenType::Break) || check(TokenType::Continue)) {
        return parseLoopControl();
    }
    if (check(TokenType::Raise)) {
        return parseRaise();
    }
    if (check(TokenType::Try)) {
        return parseTry();
    }
    if (check(TokenType::LeftBrace)) {
        Statement block;
        block.kind = StatementKind::Block;
        block.location = current().location;
        block.body = parseBlock();
        return block;
    }
    if (check(TokenType::Return)) {
        return parseReturn();
    }
    if (check(TokenType::Super) || check(TokenType::Virtual)) {
        return parseSuperConstructorCall();
    }
    error(current(), std::string("expected statement, found ") + tokenTypeName(current().type));
}

Statement Parser::parseInlineC() {
    const auto keyword = consume(TokenType::Inline, "'inline'");
    Statement statement;
    statement.kind = StatementKind::InlineC;
    statement.location = keyword.location;
    if (match(TokenType::LeftParen)) {
        if (!check(TokenType::RightParen)) {
            do {
                const auto location = current().location;
                const auto type = parseType(true);
                std::unique_ptr<Expression> target;
                if (match(TokenType::Dot)) {
                    target = std::make_unique<Expression>();
                    target->kind = ExpressionKind::ImplicitThis;
                    target->location = location;
                }
                const auto name = consume(TokenType::Identifier, "capture name");
                auto member = std::make_unique<Expression>();
                member->kind = target ? ExpressionKind::Member : ExpressionKind::Identifier;
                member->location = name.location;
                member->value = name.text;
                member->left = std::move(target);
                target = std::move(member);
                std::string captureName = name.text;
                while (match(TokenType::Dot)) {
                    const auto next = consume(TokenType::Identifier, "capture field after '.'");
                    member = std::make_unique<Expression>();
                    member->kind = ExpressionKind::Member;
                    member->location = next.location;
                    member->value = next.text;
                    member->left = std::move(target);
                    target = std::move(member);
                    captureName = next.text;
                }
                statement.inlineCaptures.push_back(
                    {type, captureName, location, std::move(target)});
            } while (match(TokenType::Comma));
        }
        consume(TokenType::RightParen, "')' after inline capture list");
    }
    const auto& body = consume(TokenType::InlineBody, "inline C block body");
    statement.inlineSource = body.text;
    consumeStatementTerminator();
    return statement;
}

Statement Parser::parseDeclaration() {
    const auto type = current();
    const auto typeName = parseType();
    const auto name = consume(TokenType::Identifier, "identifier (keywords are reserved)");
    Statement statement;
    statement.kind = StatementKind::Declaration;
    statement.location = type.location;
    statement.name = name.text;
    statement.declaredType = typeName;
    if (match(TokenType::Equal)) {
        statement.expressions.push_back(parseExpression());
    } else if (type.type == TokenType::Identifier && match(TokenType::LeftParen)) {
        auto constructor = std::make_unique<Expression>();
        constructor->kind = ExpressionKind::ConstructorCall;
        constructor->location = type.location;
        constructor->value = typeName;
        if (!check(TokenType::RightParen)) {
            do {
                constructor->arguments.push_back(parseExpression());
            } while (match(TokenType::Comma));
        }
        consume(TokenType::RightParen, "')' after constructor arguments");
        statement.expressions.push_back(std::move(constructor));
    }
    if (check(TokenType::Inline)) {
        if (!statement.expressions.empty()) {
            error(current(), "inline capture declaration cannot have an initializer");
        }
        pendingStatements_.push_back(parseInlineC());
        auto& inlineStatement = pendingStatements_.back();
        inlineStatement.inlineCaptures.push_back({typeName, name.text, type.location, nullptr});
        return statement;
    }
    consumeStatementTerminator();
    return statement;
}

Statement Parser::parseIdentifierStatement() {
    std::size_t lookahead = current_;
    if (tokens_[lookahead].type == TokenType::Identifier) {
        ++lookahead;
        while (lookahead + 1 < tokens_.size() &&
               tokens_[lookahead].type == TokenType::Dot &&
               tokens_[lookahead + 1].type == TokenType::Identifier) {
            lookahead += 2;
        }
    }
    if (lookahead < tokens_.size() &&
        tokens_[lookahead].type == TokenType::Identifier) {
        return parseDeclaration();
    }
    auto expression = parseExpression();
    Token assignmentOperator;
    if (check(TokenType::Equal) || check(TokenType::PlusEqual) ||
        check(TokenType::MinusEqual) || check(TokenType::StarEqual) ||
        check(TokenType::SlashEqual) || check(TokenType::PercentEqual)) {
        assignmentOperator = tokens_[current_++];
        Statement statement;
        statement.kind = StatementKind::Assignment;
        statement.location = expression->location;
        statement.assignmentOperator = assignmentOperator.text;
        statement.assignmentOperatorLocation = assignmentOperator.location;
        statement.target = std::move(expression);
        statement.expressions.push_back(parseExpression());
        consumeStatementTerminator();
        return statement;
    }
    if (expression->kind != ExpressionKind::Call &&
        expression->kind != ExpressionKind::ConstructorCall) {
        error(current(), "only method calls may be used as expression statements");
    }
    Statement statement;
    statement.kind = StatementKind::Expression;
    statement.location = expression->location;
    statement.expressions.push_back(std::move(expression));
    consumeStatementTerminator();
    return statement;
}

Statement Parser::parseReturn() {
    const auto keyword = consume(TokenType::Return, "'return'");
    Statement statement;
    statement.kind = StatementKind::Return;
    statement.location = keyword.location;
    // C-style optional parentheses: `return (expr)` is just a parenthesized
    // expression (already handled by parseExpression below), but a bare
    // `return ()` with nothing inside is the void-return form, equivalent to
    // plain `return`. Detect that empty-parens case explicitly so it isn't
    // parsed as "expected expression, found ')'".
    if (check(TokenType::LeftParen) && current_ + 1 < tokens_.size() &&
        tokens_[current_ + 1].type == TokenType::RightParen) {
        match(TokenType::LeftParen);
        match(TokenType::RightParen);
        consumeStatementTerminator();
        return statement;
    }
    if (!check(TokenType::Newline) && !check(TokenType::RightBrace) &&
        !check(TokenType::End)) {
        statement.expressions.push_back(parseExpression());
    }
    consumeStatementTerminator();
    return statement;
}

Statement Parser::parseSuperConstructorCall() {
    const auto keyword = current();
    Statement statement;
    statement.kind = StatementKind::SuperConstructorCall;
    statement.location = keyword.location;
    if (match(TokenType::Super)) {
        statement.virtualBaseInitializer = match(TokenType::Virtual);
    } else {
        consume(TokenType::Virtual, "'virtual'");
        statement.virtualBaseInitializer = true;
        consume(TokenType::Super, "'super' after virtual");
    }
    statement.name = consume(TokenType::Identifier, "base class name after super").text;
    consume(TokenType::LeftParen, "'(' after base class name");
    if (!check(TokenType::RightParen)) {
        do {
            statement.expressions.push_back(parseExpression());
        } while (match(TokenType::Comma));
    }
    consume(TokenType::RightParen, "')' after base constructor arguments");
    consumeStatementTerminator();
    return statement;
}

Statement Parser::parsePrint() {
    const auto keyword = consume(TokenType::Print, "'print'");
    Statement statement;
    statement.kind = StatementKind::Print;
    statement.location = keyword.location;
    consume(TokenType::LeftParen, "'(' after print");
    if (!check(TokenType::RightParen)) {
        statement.expressions.push_back(parseExpression());
        if (match(TokenType::Comma)) {
            error(previous(), "use double-quoted format-call syntax: print(\"{}\"(value))");
        }
        const auto& value = *statement.expressions.front();
        if (value.kind == ExpressionKind::String && value.formattedString &&
            value.value.find_first_of("{}") != std::string::npos) {
            error(keyword, "formatted string requires expression arguments in parentheses");
        }
    }
    consume(TokenType::RightParen, "')' after print arguments");
    consumeStatementTerminator();
    return statement;
}

Statement Parser::parseIf() {
    const auto keyword = consume(TokenType::If, "'if'");
    Statement statement;
    statement.kind = StatementKind::If;
    statement.location = keyword.location;
    consume(TokenType::LeftParen, "'(' after if");
    statement.expressions.push_back(parseExpression());
    consume(TokenType::RightParen, "')' after if condition");
    skipNewlines();
    statement.body = parseBlock();
    skipNewlines();
    if (match(TokenType::Else)) {
        statement.hasAlternate = true;
        if (check(TokenType::LeftParen)) {
            error(current(), "unconditional 'else' cannot have a condition");
        }
        statement.alternate = parseBlock();
    }
    return statement;
}

Statement Parser::parseWhile() {
    const auto keyword = consume(TokenType::While, "'while'");
    Statement statement;
    statement.kind = StatementKind::While;
    statement.location = keyword.location;
    consume(TokenType::LeftParen, "'(' after while");
    statement.expressions.push_back(parseExpression());
    consume(TokenType::RightParen, "')' after while condition");
    skipNewlines();
    statement.body = parseBlock();
    return statement;
}

Statement Parser::parseDoWhile() {
    const auto keyword = consume(TokenType::Do, "'do'");
    Statement statement;
    statement.kind = StatementKind::DoWhile;
    statement.location = keyword.location;
    skipNewlines();
    statement.body = parseBlock();
    skipNewlines();
    consume(TokenType::While, "'while' after do-while body");
    consume(TokenType::LeftParen, "'(' after while");
    statement.expressions.push_back(parseExpression());
    consume(TokenType::RightParen, "')' after do-while condition");
    return statement;
}

Statement Parser::parseForEach() {
    const auto keyword = consume(TokenType::For, "'for'");
    Statement statement;
    statement.kind = StatementKind::ForEach;
    statement.location = keyword.location;
    consume(TokenType::LeftParen, "'(' after for");
    const auto first = consume(TokenType::Identifier, "iteration variable");
    if (match(TokenType::Comma)) {
        statement.keyName = first.text;
        statement.name = consume(TokenType::Identifier, "value iteration variable").text;
    } else {
        statement.name = first.text;
    }
    consume(TokenType::In, "'in' after iteration variable");
    statement.expressions.push_back(parseExpression());
    consume(TokenType::RightParen, "')' after collection expression");
    skipNewlines();
    statement.body = parseBlock();
    return statement;
}

Statement Parser::parseLoopControl() {
    const auto keyword = current();
    ++current_;
    Statement statement;
    statement.kind = keyword.type == TokenType::Break ? StatementKind::Break
                                                      : StatementKind::Continue;
    statement.location = keyword.location;
    consumeStatementTerminator();
    return statement;
}

Statement Parser::parseRaise() {
    const auto keyword = consume(TokenType::Raise, "'raise'");
    Statement statement;
    statement.kind = StatementKind::Raise;
    statement.location = keyword.location;
    consume(TokenType::LeftParen, "'(' after raise");
    if (match(TokenType::RightParen)) {
        statement.rethrowsException = true;
    } else {
        statement.expressions.push_back(parseExpression());
        consume(TokenType::RightParen, "')' after raised expression");
    }
    consumeStatementTerminator();
    return statement;
}

Statement Parser::parseTry() {
    const auto keyword = consume(TokenType::Try, "'try'");
    Statement statement;
    statement.kind = StatementKind::Try;
    statement.location = keyword.location;
    skipNewlines();
    statement.body = parseBlock();
    skipNewlines();
    while (match(TokenType::Except)) {
        ExceptionHandler handler;
        handler.location = previous().location;
        consume(TokenType::LeftParen, "'(' after except");
        if (!check(TokenType::RightParen)) {
            handler.exceptionType = parseQualifiedIdentifier("exception class name");
        }
        consume(TokenType::RightParen, "')' after exception class name");
        if (match(TokenType::As)) {
            handler.name = consume(TokenType::Identifier, "exception binding name").text;
            handler.hasBinding = true;
        }
        skipNewlines();
        handler.body = parseBlock();
        statement.exceptionHandlers.push_back(std::move(handler));
        skipNewlines();
    }
    if (match(TokenType::Finally)) {
        statement.hasCleanup = true;
        skipNewlines();
        statement.cleanup = parseBlock();
        skipNewlines();
    }
    if (statement.exceptionHandlers.empty() && !statement.hasCleanup) {
        error(current(), "'try' requires an 'except' or 'finally' block");
    }
    return statement;
}

std::unique_ptr<Expression> Parser::parseExpression() {
    return parseOr();
}

std::unique_ptr<Expression> Parser::parseOr() {
    auto expression = parseAnd();
    while (check(TokenType::Or) || check(TokenType::OrOr)) {
        const auto operation = tokens_[current_++];
        auto combined = std::make_unique<Expression>();
        combined->kind = ExpressionKind::Binary;
        combined->location = operation.location;
        combined->value = "||";
        combined->left = std::move(expression);
        combined->right = parseAnd();
        expression = std::move(combined);
    }
    return expression;
}

std::unique_ptr<Expression> Parser::parseAnd() {
    auto expression = parseNot();
    while (check(TokenType::And) || check(TokenType::AndAnd)) {
        const auto operation = tokens_[current_++];
        auto combined = std::make_unique<Expression>();
        combined->kind = ExpressionKind::Binary;
        combined->location = operation.location;
        combined->value = "&&";
        combined->left = std::move(expression);
        combined->right = parseNot();
        expression = std::move(combined);
    }
    return expression;
}

std::unique_ptr<Expression> Parser::parseNot() {
    if (check(TokenType::Bang)) {
        const auto operation = tokens_[current_++];
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::Unary;
        expression->location = operation.location;
        expression->value = "!";
        expression->left = parseNot();
        return expression;
    }
    return parseComparison();
}

std::unique_ptr<Expression> Parser::parseComparison() {
    auto expression = parseRelational();
    while (check(TokenType::EqualEqual) || check(TokenType::BangEqual)) {
        const auto operation = tokens_[current_++];
        auto combined = std::make_unique<Expression>();
        combined->kind = ExpressionKind::Binary;
        combined->location = operation.location;
        combined->value = operation.text;
        combined->left = std::move(expression);
        combined->right = parseRelational();
        expression = std::move(combined);
    }
    return expression;
}

std::unique_ptr<Expression> Parser::parseRelational() {
    auto expression = parseAddition();
    while (check(TokenType::Is) || check(TokenType::Less) ||
           check(TokenType::LessEqual) || check(TokenType::Greater) ||
           check(TokenType::GreaterEqual)) {
        const auto operation = tokens_[current_++];
        auto combined = std::make_unique<Expression>();
        combined->location = operation.location;
        combined->left = std::move(expression);
        if (operation.type == TokenType::Is) {
            combined->kind = ExpressionKind::TypeTest;
            combined->typeLocation = current().location;
            combined->value = parseTypeTestName();
        } else {
            combined->kind = ExpressionKind::Binary;
            combined->value = operation.text;
            combined->right = parseAddition();
        }
        expression = std::move(combined);
    }
    return expression;
}

std::string Parser::parseTypeTestName() {
    if (check(TokenType::Identifier)) {
        return parseQualifiedIdentifier("type name after 'is'");
    }
    if (match(TokenType::Int)) return "int";
    if (match(TokenType::Unsigned)) return "unsigned";
    if (match(TokenType::FloatType)) return "float";
    if (match(TokenType::Bool)) return "bool";
    if (match(TokenType::StrgType)) return "String";
    if (match(TokenType::ListType)) return "list";
    if (match(TokenType::DictType)) return "dict";
    if (match(TokenType::BufferType)) return "buffer";
    if (match(TokenType::HandleType)) return "handle";
    if (match(TokenType::AnyType)) return "any";
    if (match(TokenType::TypeType)) return "type";
    if (match(TokenType::Void)) return "void";
    error(current(), std::string("expected type name after 'is', found ") +
                         tokenTypeName(current().type));
}

std::unique_ptr<Expression> Parser::parseAddition() {
    auto expression = parseMultiplication();
    while (check(TokenType::Plus) || check(TokenType::Minus)) {
        const auto operation = tokens_[current_++];
        auto combined = std::make_unique<Expression>();
        combined->kind = ExpressionKind::Binary;
        combined->location = operation.location;
        combined->value = operation.text;
        combined->left = std::move(expression);
        combined->right = parseMultiplication();
        expression = std::move(combined);
    }
    return expression;
}

std::unique_ptr<Expression> Parser::parseMultiplication() {
    auto expression = parseUnary();
    while (check(TokenType::Star) || check(TokenType::Slash) || check(TokenType::Percent)) {
        const auto operation = tokens_[current_++];
        auto combined = std::make_unique<Expression>();
        combined->kind = ExpressionKind::Binary;
        combined->location = operation.location;
        combined->value = operation.text;
        combined->left = std::move(expression);
        combined->right = parseUnary();
        expression = std::move(combined);
    }
    return expression;
}

std::unique_ptr<Expression> Parser::parseUnary() {
    if (check(TokenType::Minus) || check(TokenType::Plus)) {
        const auto operation = tokens_[current_++];
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::Unary;
        expression->location = operation.location;
        expression->value = operation.text;
        expression->left = parseUnary();
        return expression;
    }
    return parsePostfix(parsePrimary());
}

std::unique_ptr<Expression> Parser::parsePrimary() {
    const auto token = current();
    if (match(TokenType::TypeType)) {
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::TypeOf;
        expression->location = token.location;
        consume(TokenType::LeftParen, "'(' after 'type'");
        expression->left = parseExpression();
        consume(TokenType::RightParen, "')' after type operand");
        return expression;
    }
    if (check(TokenType::Int) && current_ + 1 < tokens_.size() &&
        tokens_[current_ + 1].type != TokenType::LeftParen) {
        ++current_;
        return parseTypeName(token, "int");
    }
    if (check(TokenType::Bool) && current_ + 1 < tokens_.size() &&
        tokens_[current_ + 1].type != TokenType::LeftParen) {
        ++current_;
        return parseTypeName(token, "bool");
    }
    if (check(TokenType::FloatType) && current_ + 1 < tokens_.size() &&
        tokens_[current_ + 1].type != TokenType::LeftParen) {
        ++current_;
        return parseTypeName(token, "float");
    }
    if (check(TokenType::Unsigned) && current_ + 1 < tokens_.size() &&
        tokens_[current_ + 1].type != TokenType::LeftParen) {
        ++current_;
        return parseTypeName(token, "unsigned");
    }
    if (check(TokenType::StrgType)) {
        ++current_;
        return parseTypeName(token, "String");
    }
    if (check(TokenType::ListType)) {
        ++current_;
        return parseTypeName(token, "list");
    }
    if (check(TokenType::DictType)) {
        ++current_;
        return parseTypeName(token, "dict");
    }
    if (check(TokenType::BufferType) && current_ + 1 < tokens_.size() &&
        tokens_[current_ + 1].type == TokenType::LeftBracket) {
        ++current_;
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::BufferLiteral;
        expression->location = token.location;
        consume(TokenType::LeftBracket, "'[' after buffer");
        if (!check(TokenType::RightBracket)) {
            do {
                expression->arguments.push_back(parseExpression());
            } while (match(TokenType::Comma));
        }
        consume(TokenType::RightBracket, "']' after buffer elements");
        return expression;
    }
    if (check(TokenType::BufferType) && current_ + 1 < tokens_.size() &&
        tokens_[current_ + 1].type != TokenType::LeftParen) {
        ++current_;
        return parseTypeName(token, "buffer");
    }
    if (check(TokenType::HandleType)) {
        ++current_;
        return parseTypeName(token, "handle");
    }
    if (check(TokenType::AnyType)) {
        ++current_;
        return parseTypeName(token, "any");
    }
    if (match(TokenType::BufferType)) {
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::BufferConstructor;
        expression->location = token.location;
        consume(TokenType::LeftParen, "'(' after buffer");
        if (!check(TokenType::RightParen)) {
            do {
                expression->arguments.push_back(parseExpression());
            } while (match(TokenType::Comma));
        }
        consume(TokenType::RightParen, "')' after buffer length");
        return expression;
    }
    if (check(TokenType::Bool) || check(TokenType::Int) || check(TokenType::Unsigned) ||
        check(TokenType::FloatType)) {
        const auto castTargetType = current().type == TokenType::Bool     ? "bool"
                                    : current().type == TokenType::Int      ? "int"
                                    : current().type == TokenType::Unsigned ? "unsigned"
                                                                             : "float";
        ++current_;
        consume(TokenType::LeftParen, "'(' after explicit cast type name");
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::Cast;
        expression->location = token.location;
        expression->value = castTargetType;
        expression->arguments.push_back(parseExpression());
        consume(TokenType::RightParen, "')' after cast operand");
        return expression;
    }
    if (match(TokenType::UnsignedInteger)) {
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::Unsigned;
        expression->location = token.location;
        expression->value = token.text;
        return expression;
    }
    if (match(TokenType::Float)) {
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::Float;
        expression->location = token.location;
        expression->value = token.text;
        return expression;
    }
    if (match(TokenType::Integer)) {
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::Integer;
        expression->location = token.location;
        expression->value = token.text;
        return expression;
    }
    if (match(TokenType::True) || match(TokenType::False)) {
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::Boolean;
        expression->location = token.location;
        expression->value = token.type == TokenType::True ? "true" : "false";
        return expression;
    }
    if (match(TokenType::String)) {
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::String;
        expression->location = token.location;
        expression->value = token.text;
        expression->formattedString = token.formattedString;
        return expression;
    }
    if (match(TokenType::Identifier)) {
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::Identifier;
        expression->location = token.location;
        expression->value = token.text;
        return expression;
    }
    if (match(TokenType::Null)) {
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::Null;
        expression->location = token.location;
        return expression;
    }
    if (match(TokenType::LeftParen)) {
        auto expression = parseExpression();
        consume(TokenType::RightParen, "')' after expression");
        return expression;
    }
    if (match(TokenType::LeftBracket)) {
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::ArrayLiteral;
        expression->location = token.location;
        if (!check(TokenType::RightBracket)) {
            do {
                expression->arguments.push_back(parseExpression());
            } while (match(TokenType::Comma));
        }
        consume(TokenType::RightBracket, "']' after list elements");
        return expression;
    }
    if (match(TokenType::LeftBrace)) {
        auto expression = std::make_unique<Expression>();
        expression->kind = ExpressionKind::MapLiteral;
        expression->location = token.location;
        if (!check(TokenType::RightBrace)) {
            do {
                expression->arguments.push_back(parseExpression());
                consume(TokenType::Colon, "':' between dict key and value");
                expression->arguments.push_back(parseExpression());
            } while (match(TokenType::Comma));
        }
        consume(TokenType::RightBrace, "'}' after dict entries");
        return expression;
    }
    error(current(), std::string("expected expression, found ") + tokenTypeName(current().type));
}

std::unique_ptr<Expression> Parser::parseTypeName(const Token& token, std::string name) {
    auto expression = std::make_unique<Expression>();
    expression->kind = ExpressionKind::TypeName;
    expression->location = token.location;
    expression->typeLocation = token.location;
    expression->value = std::move(name);
    return expression;
}

std::unique_ptr<Expression> Parser::parsePostfix(std::unique_ptr<Expression> expression) {
    for (;;) {
        if (match(TokenType::As)) {
            auto cast = std::make_unique<Expression>();
            cast->kind = ExpressionKind::ObjectCast;
            cast->location = previous().location;
            cast->typeLocation = current().location;
            cast->value = parseQualifiedIdentifier("class name after 'as'");
            cast->left = std::move(expression);
            expression = std::move(cast);
            continue;
        }
        if (match(TokenType::LeftBracket)) {
            auto access = std::make_unique<Expression>();
            access->location = previous().location;
            access->left = std::move(expression);
            const auto omittedValue = [&access](const std::string& value) {
                auto omitted = std::make_unique<Expression>();
                omitted->kind = ExpressionKind::Integer;
                omitted->value = value;
                omitted->location = access->location;
                return omitted;
            };
            if (match(TokenType::Colon)) {
                access->kind = ExpressionKind::Slice;
                access->sliceHasStart = false;
                access->arguments.push_back(omittedValue("0"));
                access->sliceHasEnd = !check(TokenType::Colon) &&
                                      !check(TokenType::RightBracket);
                access->arguments.push_back(access->sliceHasEnd
                                                ? parseExpression()
                                                : omittedValue("0"));
                access->sliceHasStep = match(TokenType::Colon);
                access->arguments.push_back(access->sliceHasStep &&
                                                    !check(TokenType::RightBracket)
                                                ? parseExpression()
                                                : omittedValue("1"));
            } else {
                auto start = parseExpression();
                if (match(TokenType::Colon)) {
                    access->kind = ExpressionKind::Slice;
                    access->arguments.push_back(std::move(start));
                    access->sliceHasEnd = !check(TokenType::Colon) &&
                                          !check(TokenType::RightBracket);
                    access->arguments.push_back(access->sliceHasEnd
                                                    ? parseExpression()
                                                    : omittedValue("0"));
                    access->sliceHasStep = match(TokenType::Colon);
                    access->arguments.push_back(access->sliceHasStep &&
                                                        !check(TokenType::RightBracket)
                                                    ? parseExpression()
                                                    : omittedValue("1"));
                } else {
                    access->kind = ExpressionKind::Index;
                    access->arguments.push_back(std::move(start));
                }
            }
            consume(TokenType::RightBracket, "']' after index or slice");
            expression = std::move(access);
            continue;
        }
        if (match(TokenType::Dot)) {
            const auto member = consume(TokenType::Identifier, "member name after '.'");
            auto access = std::make_unique<Expression>();
            access->kind = ExpressionKind::Member;
            access->location = member.location;
            access->value = member.text;
            access->left = std::move(expression);
            expression = std::move(access);
            continue;
        }
        if (check(TokenType::LeftParen) &&
            expression->kind == ExpressionKind::String &&
            !expression->formattedString) {
            error(current(), "format arguments require a double-quoted string literal");
        }
        if (check(TokenType::LeftParen) &&
            expression->kind == ExpressionKind::String &&
            expression->formattedString) {
            ++current_;
            expression->kind = ExpressionKind::FormatString;
            if (!check(TokenType::RightParen)) {
                do {
                    if (check(TokenType::Identifier) && current_ + 1 < tokens_.size() &&
                        tokens_[current_ + 1].type == TokenType::Equal) {
                        const auto name = consume(TokenType::Identifier,
                                                  "named format argument");
                        if (std::find(expression->argumentNames.begin(),
                                      expression->argumentNames.end(), name.text) !=
                            expression->argumentNames.end()) {
                            error(name, "duplicate named format argument '" + name.text + "'");
                        }
                        if (std::any_of(expression->argumentNames.begin(),
                                        expression->argumentNames.end(),
                                        [](const std::string& value) {
                                            return value.empty();
                                        })) {
                            error(name, "named and positional format arguments cannot be mixed");
                        }
                        consume(TokenType::Equal, "'=' after named format argument");
                        expression->argumentNames.push_back(name.text);
                        expression->argumentNameLocations.push_back(name.location);
                    } else {
                        if (std::any_of(expression->argumentNames.begin(),
                                        expression->argumentNames.end(),
                                        [](const std::string& value) {
                                            return !value.empty();
                                        })) {
                            error(current(),
                                  "named and positional format arguments cannot be mixed");
                        }
                        expression->argumentNames.emplace_back();
                        expression->argumentNameLocations.emplace_back();
                    }
                    expression->arguments.push_back(parseExpression());
                } while (match(TokenType::Comma));
            }
            consume(TokenType::RightParen, "')' after format arguments");
            validateFormatString(*expression);
            continue;
        }
        if (check(TokenType::LeftParen) &&
            (expression->kind == ExpressionKind::Identifier ||
             expression->kind == ExpressionKind::Member)) {
            ++current_;
            const bool constructorCall = expression->kind == ExpressionKind::Identifier;
            auto call = std::make_unique<Expression>();
            call->kind = constructorCall ? ExpressionKind::ConstructorCall : ExpressionKind::Call;
            call->location = expression->location;
            if (constructorCall) {
                call->value = expression->value;
            } else {
                call->left = std::move(expression);
            }
            if (!check(TokenType::RightParen)) {
                do {
                    call->arguments.push_back(parseExpression());
                } while (match(TokenType::Comma));
            }
            consume(TokenType::RightParen, "')' after call arguments");
            expression = std::move(call);
            continue;
        }
        return expression;
    }
}

} // namespace simp
